import{_ as a,H as o,f as t,i as s}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"plan","description":"","frontmatter":{},"headers":[],"relativePath":"ja/skills/plan.md","filePath":"ja/skills/plan.md"}'),l={name:"ja/skills/plan.md"};function d(c,e,n,i,p,r){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;plan&quot;">​</a></h1><p><code>plan</code> スキルは、承認された仕様書を <code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code> の実行可能なマイルストーンタスクに分解します。仕様書への参照のみを記述し、背景・アーキテクチャ・理由は重複記述しません。</p><h2 id="ローリングウェーブとマルチモジュールトポロジー" tabindex="-1">ローリングウェーブとマルチモジュールトポロジー <a class="header-anchor" href="#ローリングウェーブとマルチモジュールトポロジー" aria-label="Permalink to &quot;ローリングウェーブとマルチモジュールトポロジー&quot;">​</a></h2><ul><li><strong>ローリングウェーブ（Rolling wave）</strong>：仕様書が <code>docs/ROADMAP.md</code> の <code>milestone: MN</code> を参照している場合、そのマイルストーンのみを展開し、残りは1行のスタブとして残します。<code>ship</code> 後に次のマイルストーンを確認してから展開し、目標が本質的に変わった場合のみ <code>design</code> に戻ります。</li><li><strong>マルチモジュールトポロジー</strong>：<code>topology=multi-module</code> が宣言されている場合は、<a href="./multi-module.html">マルチモジュールプロトコル</a> を読み、Coordinator ワークスペース計画の先頭にモード宣言ブロック（<code>topology: multi-module</code>、<code>change-set</code>、<code>coordinator</code>、<code>repos</code>、各モジュール計画パス、統合タスク）を記述します。各タスクは1つの <code>repository:</code> と1つの <code>module:</code> に属し、「契約 → 利用側 → ローカル受入 → 統合 → 依存順コミット」の順に並べます。</li></ul><h2 id="マイルストーンタスク-各-30〜60-分" tabindex="-1">マイルストーンタスク（各 30〜60 分） <a class="header-anchor" href="#マイルストーンタスク-各-30〜60-分" aria-label="Permalink to &quot;マイルストーンタスク（各 30〜60 分）&quot;">​</a></h2><p>各タスクは見出しではなくチェックボックス（<code>- [ ] T&lt;n&gt;: &lt;名前&gt;</code>）として記述します：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>goal:       &lt;1行の目的&gt;</span></span>
<span class="line"><span>files:      &lt;対象パス&gt;</span></span>
<span class="line"><span>acceptance: &lt;実行可能なテスト、コマンド、または明示的な手動検証手順&gt;</span></span>
<span class="line"><span>spec:       &lt;docs/staging/specs/...#anchor&gt;</span></span></code></pre></div><p>共有契約・状態・受入境界が閉じており、書き込み範囲が重複しない独立タスクのみ <code>[parallel] T3, T4, T5</code> を付けます。原子的な詳細ステップへの展開は <code>subagents</code> 派遣時まで遅延させます。</p><h2 id="ハンドオフゲート" tabindex="-1">ハンドオフゲート <a class="header-anchor" href="#ハンドオフゲート" aria-label="Permalink to &quot;ハンドオフゲート&quot;">​</a></h2><p><code>&lt;gate&gt;</code><code>tdd</code> または <code>subagents</code> に引き渡す前に、<code>docs/staging/plans/YYYY-MM-DD-&lt;topic&gt;.md</code>（マルチモジュール時は影響する各モジュールの計画ファイルを含む）がディスク上に存在し、ユーザー確認を得ている必要があります。 <code>&lt;/gate&gt;</code></p>`,10)])])}const u=a(l,[["render",d]]);export{h as __pageData,u as default};
